package ru.kstolu.app;
import android.app.*;import org.json.*;import java.util.*;
/** Pure presentation of verified recipe fields; never invent stock quantities or missing metadata. */
final class RecipeFacts {
 static String coverage(JSONObject r){if(!r.has("pantry"))return "";JSONArray a=r.optJSONArray("ingredients");int have=0,required=0,basic=0,missing=0;String lastMissing="";for(int i=0;i<a.length();i++){String s=a.optJSONObject(i).optString("availability");if(s.equals("basic")){basic++;continue;}required++;if(s.equals("present"))have++;else{missing++;lastMissing=a.optJSONObject(i).optString("name");}}return "Есть "+have+" из "+required+" ингредиентов"+(missing==1?" · не хватает: "+lastMissing:missing>1?" · не хватает "+missing:basic>0?" · + базовые":"");}
 static String difficulty(JSONObject r){JSONObject d=r.optJSONObject("difficulty");if(d==null)return "";String label=d.optString("level").equals("easy")?"Просто":"Потребует внимания";JSONArray reasons=d.optJSONArray("reasons");if(reasons!=null&&reasons.length()>0){ArrayList<String> parts=new ArrayList<>();for(int i=0;i<reasons.length();i++)parts.add(reasons.optString(i));label+=" · "+String.join("; ",parts);}return label;}
 static String difficultyLabel(JSONObject r){JSONObject d=r.optJSONObject("difficulty");return d==null?"":d.optString("level").equals("easy")?"Просто":"Потребует внимания";}
 static void difficultyDetails(Activity host,JSONObject r){new AlertDialog.Builder(host).setTitle(difficultyLabel(r)).setMessage(difficulty(r)+"\n\nОриентир по этапам рецепта; опыт и оборудование влияют на сложность.").setPositiveButton("Понятно",null).show();}
 static void availabilityDetails(Activity host,JSONObject r){JSONArray a=r.optJSONArray("ingredients");StringBuilder b=new StringBuilder();for(String status:new String[]{"missing","present","basic"}){ArrayList<String> names=new ArrayList<>();for(int i=0;i<a.length();i++)if(a.optJSONObject(i).optString("availability").equals(status))names.add(a.optJSONObject(i).optString("name"));if(!names.isEmpty())b.append(status.equals("missing")?"Не хватает":status.equals("present")?"Есть в списке":"Базовые — проверьте наличие").append(":\n").append(String.join(", ",names)).append("\n\n");}if(!difficulty(r).isEmpty())b.append(difficulty(r)).append("\n\n");b.append("Наличие по подтверждённому списку; достаточное количество и свежесть не проверены.");new AlertDialog.Builder(host).setTitle("Продукты для блюда").setMessage(b.toString()).setPositiveButton("Понятно",null).show();}
 static void priceDetails(Activity host,JSONObject r,int servings,String currency){StringBuilder b=new StringBuilder("Примерные цены за указанное количество, не актуальный прайс магазина.\n\n");JSONArray a=r.optJSONArray("ingredients");for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i),p=x.optJSONObject("price");b.append(x.optString("name")).append(": ");if(p==null||p.optDouble("quantity")<=0)b.append("не учтён — цена неизвестна");else{double f=x.optDouble("amount")*servings/r.optInt("servings",2)/p.optDouble("quantity");b.append(String.format(Locale.getDefault(),"≈ %.0f–%.0f %s",p.optDouble("low")*f,p.optDouble("high")*f,currency)).append(p.optString("source").equals("receipt")?" · чек":" · оценка");}b.append('\n');}new AlertDialog.Builder(host).setTitle("Что учтено в стоимости").setMessage(b.toString()).setPositiveButton("Понятно",null).show();}
}
